"use strict";(self.webpackChunk_app_children_router_0_1_9=self.webpackChunk_app_children_router_0_1_9||[]).push([[666],{69666(n,e,t){t.d(e,{A:()=>i});var a=t(22536),o=t(4090),r=t(28793);const i={name:"app-children-router",summary:"<h1>App Children Router</h1>\n<p>\u4e00\u4e2a\u8f7b\u91cf\u7ea7\u7684 React \u5b50\u8def\u7531\u7ba1\u7406\u5e93\uff0c\u4e13\u4e3a\u9700\u8981\u52a8\u6001\u8def\u7531\u914d\u7f6e\u7684\u5e94\u7528\u8bbe\u8ba1\u3002\u652f\u6301\u52a8\u6001\u52a0\u8f7d\u9875\u9762\u7ec4\u4ef6\u3001\u5185\u7f6e\u9519\u8bef\u5904\u7406\u548c 404 \u9875\u9762\u914d\u7f6e\uff0c\u5e76\u63d0\u4f9b\u56fd\u9645\u5316\u652f\u6301\u3002</p>\n<h2>\u6838\u5fc3\u7279\u6027</h2>\n<ul>\n<li><strong>\u52a8\u6001\u8def\u7531\u52a0\u8f7d</strong>\uff1a\u57fa\u4e8e <code>@loadable/component</code> \u5b9e\u73b0\u6309\u9700\u52a0\u8f7d\uff0c\u63d0\u5347\u5e94\u7528\u6027\u80fd</li>\n<li><strong>\u5185\u7f6e\u9519\u8bef\u5904\u7406</strong>\uff1a\u81ea\u52a8\u5904\u7406\u9519\u8bef\u9875\u9762\uff08403\u3001404\u3001500\uff09\u548c 404 \u9875\u9762\uff0c\u51cf\u5c11\u91cd\u590d\u4ee3\u7801</li>\n<li><strong>\u56fd\u9645\u5316\u652f\u6301</strong>\uff1a\u5185\u7f6e\u4e2d\u82f1\u6587\u8bed\u8a00\u5305\uff0c\u8f7b\u677e\u9002\u914d\u591a\u8bed\u8a00\u73af\u5883</li>\n<li><strong>\u9ad8\u5ea6\u53ef\u5b9a\u5236</strong>\uff1a\u652f\u6301\u81ea\u5b9a\u4e49\u9519\u8bef\u9875\u9762\u3001\u52a0\u8f7d\u72b6\u6001\u3001\u5168\u5c40\u914d\u7f6e</li>\n<li><strong>\u5d4c\u5957\u8def\u7531\u652f\u6301</strong>\uff1a\u914d\u5408 React Router v6 \u5b9e\u73b0\u590d\u6742\u7684\u5d4c\u5957\u8def\u7531\u7ed3\u6784</li>\n<li><strong>TypeScript \u652f\u6301</strong>\uff1a\u63d0\u4f9b\u5b8c\u6574\u7684\u7c7b\u578b\u58f0\u660e</li>\n</ul>\n<h2>\u5b89\u88c5</h2>\n<pre><code class=\"language-bash\">npm install @kne/app-children-router\n# \u6216\nyarn add @kne/app-children-router\n</code></pre>\n<h2>\u5feb\u901f\u5f00\u59cb</h2>\n<pre><code class=\"language-jsx\">import AppChildrenRouter from '@kne/app-children-router';\nimport { BrowserRouter, Routes, Route } from 'react-router-dom';\n\nfunction App() {\n  return (\n    &lt;BrowserRouter&gt;\n      &lt;Routes&gt;\n        &lt;Route\n          path=\"app/*\"\n          element={\n            &lt;AppChildrenRouter\n              errorPage\n              notFoundPage\n              baseUrl=\"/app\"\n              list={[\n                {\n                  index: true,\n                  loader: async () =&gt; import('./pages/Home')\n                },\n                {\n                  path: 'dashboard',\n                  loader: async () =&gt; import('./pages/Dashboard')\n                }\n              ]}\n            /&gt;\n          }\n        /&gt;\n      &lt;/Routes&gt;\n    &lt;/BrowserRouter&gt;\n  );\n}\n</code></pre>\n<h2>\u9002\u7528\u573a\u666f</h2>\n<ul>\n<li>\u9700\u8981\u52a8\u6001\u8def\u7531\u7ba1\u7406\u7684 React \u5e94\u7528</li>\n<li>\u591a\u8bed\u8a00\u548c\u56fd\u9645\u5316\u5e94\u7528</li>\n<li>\u590d\u6742\u8def\u7531\u7ed3\u6784\u548c\u5d4c\u5957\u8def\u7531\u573a\u666f</li>\n<li>\u9700\u8981\u7edf\u4e00\u9519\u8bef\u5904\u7406\u7684\u5e94\u7528</li>\n</ul>",description:"\u5b9a\u4e49\u5e94\u7528\u5b50\u8def\u7531",packageName:"@kne/app-children-router",api:"<h1>API \u6587\u6863</h1>\n<h2>\u6838\u5fc3\u7ec4\u4ef6</h2>\n<h3>AppChildrenRouter</h3>\n<p>\u4e3b\u8def\u7531\u7ec4\u4ef6\uff0c\u7528\u4e8e\u6e32\u67d3\u52a8\u6001\u8def\u7531\u914d\u7f6e\u3002</p>\n<h4>\u5c5e\u6027</h4>\n<table>\n<thead>\n<tr>\n<th>\u5c5e\u6027</th>\n<th>\u7c7b\u578b</th>\n<th>\u9ed8\u8ba4\u503c</th>\n<th>\u63cf\u8ff0</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>list</code></td>\n<td><code>Array&lt;RouteConfig&gt;</code></td>\n<td><code>[]</code></td>\n<td>\u8def\u7531\u914d\u7f6e\u5217\u8868\uff0c\u6bcf\u9879\u5305\u542b path\u3001loader\u3001element\u3001elementProps \u7b49\u5c5e\u6027</td>\n</tr>\n<tr>\n<td><code>element</code></td>\n<td><code>ReactNode</code></td>\n<td>-</td>\n<td>\u7236\u8def\u7531\u5143\u7d20\uff0c\u7528\u4e8e\u5d4c\u5957\u8def\u7531\u573a\u666f\uff0c\u914d\u5408 <code>children</code> \u4f7f\u7528</td>\n</tr>\n<tr>\n<td><code>errorPage</code></td>\n<td><code>ReactNode | boolean</code></td>\n<td>-</td>\n<td>\u81ea\u5b9a\u4e49\u9519\u8bef\u9875\u9762\uff0c\u4f20\u5165 <code>true</code> \u4f7f\u7528\u9ed8\u8ba4 Error \u7ec4\u4ef6</td>\n</tr>\n<tr>\n<td><code>notFoundPage</code></td>\n<td><code>ReactNode | boolean</code></td>\n<td>-</td>\n<td>\u81ea\u5b9a\u4e49 404 \u9875\u9762\uff0c\u4f20\u5165 <code>true</code> \u4f7f\u7528\u9ed8\u8ba4 NotFound \u7ec4\u4ef6</td>\n</tr>\n<tr>\n<td><code>loading</code></td>\n<td><code>ReactNode</code></td>\n<td>-</td>\n<td>\u9875\u9762\u52a0\u8f7d\u65f6\u7684\u8fc7\u6e21\u7ec4\u4ef6\uff0c\u8986\u76d6\u5168\u5c40\u914d\u7f6e</td>\n</tr>\n<tr>\n<td><code>children</code></td>\n<td><code>ReactNode</code></td>\n<td>-</td>\n<td>\u672a\u5339\u914d\u8def\u7531\u65f6\u7684\u56de\u9000\u5185\u5bb9\uff0c\u901a\u5e38\u914d\u5408 <code>notFoundPage</code> \u4f7f\u7528</td>\n</tr>\n<tr>\n<td><code>baseUrl</code></td>\n<td><code>string</code></td>\n<td>-</td>\n<td>\u8def\u7531\u57fa\u7840\u8def\u5f84\uff0c\u7528\u4e8e\u9519\u8bef\u9875\u9762\u8fd4\u56de\u9996\u9875\u5bfc\u822a</td>\n</tr>\n</tbody>\n</table>\n<h4>RouteConfig \u914d\u7f6e\u9879</h4>\n<table>\n<thead>\n<tr>\n<th>\u5c5e\u6027</th>\n<th>\u7c7b\u578b</th>\n<th>\u63cf\u8ff0</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>path</code></td>\n<td><code>string</code></td>\n<td>\u8def\u7531\u8def\u5f84</td>\n</tr>\n<tr>\n<td><code>index</code></td>\n<td><code>boolean</code></td>\n<td>\u662f\u5426\u4e3a\u7d22\u5f15\u8def\u7531</td>\n</tr>\n<tr>\n<td><code>loader</code></td>\n<td><code>() =&gt; Promise&lt;{ default: Component }&gt;</code></td>\n<td>\u52a8\u6001\u52a0\u8f7d\u7ec4\u4ef6\u7684\u51fd\u6570</td>\n</tr>\n<tr>\n<td><code>element</code></td>\n<td><code>ReactNode</code></td>\n<td>\u76f4\u63a5\u6307\u5b9a\u8def\u7531\u5143\u7d20\uff0c\u4e0e loader \u4e8c\u9009\u4e00</td>\n</tr>\n<tr>\n<td><code>elementProps</code></td>\n<td><code>object</code></td>\n<td>\u4f20\u9012\u7ed9\u52a0\u8f7d\u7ec4\u4ef6\u7684\u989d\u5916\u5c5e\u6027</td>\n</tr>\n</tbody>\n</table>\n<hr>\n<h3>Error</h3>\n<p>\u9ed8\u8ba4\u9519\u8bef\u9875\u9762\u7ec4\u4ef6\uff0c\u652f\u6301\u56fd\u9645\u5316\u3002</p>\n<h4>\u5c5e\u6027</h4>\n<table>\n<thead>\n<tr>\n<th>\u5c5e\u6027</th>\n<th>\u7c7b\u578b</th>\n<th>\u9ed8\u8ba4\u503c</th>\n<th>\u63cf\u8ff0</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>status</code></td>\n<td><code>number</code></td>\n<td><code>500</code></td>\n<td>HTTP \u9519\u8bef\u72b6\u6001\u7801\uff0c\u652f\u6301 404\u3001403\u3001500</td>\n</tr>\n<tr>\n<td><code>msg</code></td>\n<td><code>string</code></td>\n<td>-</td>\n<td>\u9519\u8bef\u63cf\u8ff0\u4fe1\u606f</td>\n</tr>\n<tr>\n<td><code>baseUrl</code></td>\n<td><code>string</code></td>\n<td>-</td>\n<td>\u8fd4\u56de\u9996\u9875\u7684\u57fa\u7840\u8def\u5f84</td>\n</tr>\n</tbody>\n</table>\n<hr>\n<h3>NotFound</h3>\n<p>\u9ed8\u8ba4 404 \u9875\u9762\u7ec4\u4ef6\uff0c\u652f\u6301\u56fd\u9645\u5316\u3002</p>\n<h4>\u5c5e\u6027</h4>\n<table>\n<thead>\n<tr>\n<th>\u5c5e\u6027</th>\n<th>\u7c7b\u578b</th>\n<th>\u9ed8\u8ba4\u503c</th>\n<th>\u63cf\u8ff0</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>baseUrl</code></td>\n<td><code>string</code></td>\n<td>-</td>\n<td>\u8fd4\u56de\u9996\u9875\u7684\u57fa\u7840\u8def\u5f84</td>\n</tr>\n</tbody>\n</table>\n<hr>\n<h2>\u5de5\u5177\u51fd\u6570</h2>\n<h3>loadableWithProps</h3>\n<p>\u52a8\u6001\u52a0\u8f7d\u7ec4\u4ef6\u5e76\u6ce8\u5165\u5c5e\u6027\u3002</p>\n<h4>\u53c2\u6570</h4>\n<table>\n<thead>\n<tr>\n<th>\u53c2\u6570</th>\n<th>\u7c7b\u578b</th>\n<th>\u63cf\u8ff0</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>loader</code></td>\n<td><code>() =&gt; Promise&lt;{ default: Component }&gt;</code></td>\n<td>\u52a8\u6001\u52a0\u8f7d\u51fd\u6570</td>\n</tr>\n<tr>\n<td><code>props</code></td>\n<td><code>object</code></td>\n<td>\u4f20\u9012\u7ed9\u7ec4\u4ef6\u7684\u5c5e\u6027</td>\n</tr>\n<tr>\n<td><code>loading</code></td>\n<td><code>ReactNode</code></td>\n<td>\u52a0\u8f7d\u4e2d\u7684\u8fc7\u6e21\u7ec4\u4ef6</td>\n</tr>\n</tbody>\n</table>\n<h4>\u8fd4\u56de\u503c</h4>\n<p><code>ReactNode</code> - \u52a0\u8f7d\u5b8c\u6210\u7684\u7ec4\u4ef6</p>\n<h4>\u793a\u4f8b</h4>\n<pre><code class=\"language-javascript\">const PageComponent = loadableWithProps(\n  async () =&gt; import('./Page'),\n  { title: '\u9875\u9762\u6807\u9898' },\n  &lt;Spin /&gt;\n);\n</code></pre>\n<hr>\n<h3>preset</h3>\n<p>\u5168\u5c40\u53c2\u6570\u914d\u7f6e\u51fd\u6570\uff0c\u7528\u4e8e\u8bbe\u7f6e\u9ed8\u8ba4\u503c\u3002</p>\n<h4>\u53c2\u6570</h4>\n<table>\n<thead>\n<tr>\n<th>\u53c2\u6570</th>\n<th>\u7c7b\u578b</th>\n<th>\u63cf\u8ff0</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>options</code></td>\n<td><code>object</code></td>\n<td>\u914d\u7f6e\u9879</td>\n</tr>\n</tbody>\n</table>\n<h4>\u914d\u7f6e\u9879</h4>\n<table>\n<thead>\n<tr>\n<th>\u5c5e\u6027</th>\n<th>\u7c7b\u578b</th>\n<th>\u9ed8\u8ba4\u503c</th>\n<th>\u63cf\u8ff0</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>errorPage</code></td>\n<td><code>ReactNode</code></td>\n<td>-</td>\n<td>\u9ed8\u8ba4\u9519\u8bef\u9875\u9762</td>\n</tr>\n<tr>\n<td><code>notFoundPage</code></td>\n<td><code>ReactNode</code></td>\n<td>-</td>\n<td>\u9ed8\u8ba4 404 \u9875\u9762</td>\n</tr>\n<tr>\n<td><code>loading</code></td>\n<td><code>ReactNode</code></td>\n<td><code>&lt;Spin /&gt;</code></td>\n<td>\u9ed8\u8ba4\u52a0\u8f7d\u72b6\u6001\u7ec4\u4ef6</td>\n</tr>\n</tbody>\n</table>\n<h4>\u793a\u4f8b</h4>\n<pre><code class=\"language-javascript\">import { preset } from '@kne/app-children-router';\n\npreset({\n  loading: &lt;CustomLoading /&gt;,\n  errorPage: &lt;CustomError /&gt;,\n  notFoundPage: &lt;CustomNotFound /&gt;\n});\n</code></pre>",example:{isFull:!0,className:"",style:"",list:[{title:"\u57fa\u7840\u7528\u6cd5",description:"\u5c55\u793a AppChildrenRouter \u7684\u57fa\u672c\u4f7f\u7528\u65b9\u6cd5\uff0c\u5305\u62ec\u8def\u7531\u914d\u7f6e\u3001\u9519\u8bef\u9875\u9762\u548c 404 \u9875\u9762",code:"const { default: AppChildrenRouter, loadableWithProps } = _AppChildrenRouter;\nconst { Route, Routes, Link, useNavigate, Navigate } = _reactRouterDom;\nconst { Flex, Card, Button, Table, Descriptions, Statistic, Row, Col, Typography, Space } = antd;\n\nconst { Title, Text } = Typography;\n\n// \u7528\u6237\u7ba1\u7406\u9996\u9875 - \u5c55\u793a\u6570\u636e\u6982\u89c8\nconst HomePage = () => {\n  const stats = [\n    { title: '\u603b\u7528\u6237\u6570', value: 12580 },\n    { title: '\u4eca\u65e5\u65b0\u589e', value: 128 },\n    { title: '\u6d3b\u8dc3\u7528\u6237', value: 3560 },\n    { title: '\u5f85\u5ba1\u6838', value: 23 }\n  ];\n\n  return (\n    <div style={{ padding: 24 }}>\n      <Title level={4}>\u6570\u636e\u6982\u89c8</Title>\n      <Row gutter={16} style={{ marginBottom: 24 }}>\n        {stats.map((item, index) => (\n          <Col span={6} key={index}>\n            <Card>\n              <Statistic title={item.title} value={item.value} />\n            </Card>\n          </Col>\n        ))}\n      </Row>\n    </div>\n  );\n};\n\n// \u7528\u6237\u5217\u8868\u9875\u9762 - \u5c55\u793a\u5217\u8868\u6570\u636e\nconst UserListPage = () => {\n  const columns = [\n    { title: '\u7528\u6237ID', dataIndex: 'id', key: 'id' },\n    { title: '\u7528\u6237\u540d', dataIndex: 'username', key: 'username' },\n    { title: '\u90ae\u7bb1', dataIndex: 'email', key: 'email' },\n    { title: '\u6ce8\u518c\u65f6\u95f4', dataIndex: 'registerTime', key: 'registerTime' },\n    { \n      title: '\u72b6\u6001', \n      dataIndex: 'status', \n      key: 'status',\n      render: (status) => (\n        <span style={{ color: status === 'active' ? '#52c41a' : '#ff4d4f' }}>\n          {status === 'active' ? '\u6b63\u5e38' : '\u5df2\u7981\u7528'}\n        </span>\n      )\n    },\n    {\n      title: '\u64cd\u4f5c',\n      key: 'action',\n      render: (_, record) => (\n        <Space>\n          <Link to={`/app/user/${record.id}`}>\u67e5\u770b</Link>\n          <a>\u7f16\u8f91</a>\n        </Space>\n      )\n    }\n  ];\n\n  const mockData = [\n    { id: 'U001', username: '\u5f20\u4e09', email: 'zhangsan@example.com', registerTime: '2024-01-15', status: 'active' },\n    { id: 'U002', username: '\u674e\u56db', email: 'lisi@example.com', registerTime: '2024-02-20', status: 'active' },\n    { id: 'U003', username: '\u738b\u4e94', email: 'wangwu@example.com', registerTime: '2024-03-10', status: 'inactive' }\n  ];\n\n  return (\n    <div style={{ padding: 24 }}>\n      <Title level={4}>\u7528\u6237\u5217\u8868</Title>\n      <Table columns={columns} dataSource={mockData} rowKey=\"id\" pagination={{ pageSize: 10 }} />\n    </div>\n  );\n};\n\n// \u7528\u6237\u8be6\u60c5\u9875\u9762 - \u5c55\u793a\u8be6\u7ec6\u4fe1\u606f\nconst UserDetailPage = () => {\n  const mockUser = {\n    id: 'U001',\n    username: '\u5f20\u4e09',\n    email: 'zhangsan@example.com',\n    phone: '138****8888',\n    registerTime: '2024-01-15 10:30:00',\n    lastLoginTime: '2024-03-20 15:45:00',\n    status: 'active',\n    vipLevel: '\u9ec4\u91d1\u4f1a\u5458'\n  };\n\n  return (\n    <div style={{ padding: 24 }}>\n      <Title level={4}>\u7528\u6237\u8be6\u60c5</Title>\n      <Card>\n        <Descriptions column={2} bordered>\n          <Descriptions.Item label=\"\u7528\u6237ID\">{mockUser.id}</Descriptions.Item>\n          <Descriptions.Item label=\"\u7528\u6237\u540d\">{mockUser.username}</Descriptions.Item>\n          <Descriptions.Item label=\"\u90ae\u7bb1\">{mockUser.email}</Descriptions.Item>\n          <Descriptions.Item label=\"\u624b\u673a\u53f7\">{mockUser.phone}</Descriptions.Item>\n          <Descriptions.Item label=\"\u6ce8\u518c\u65f6\u95f4\">{mockUser.registerTime}</Descriptions.Item>\n          <Descriptions.Item label=\"\u6700\u540e\u767b\u5f55\">{mockUser.lastLoginTime}</Descriptions.Item>\n          <Descriptions.Item label=\"\u4f1a\u5458\u7b49\u7ea7\">{mockUser.vipLevel}</Descriptions.Item>\n          <Descriptions.Item label=\"\u72b6\u6001\">{mockUser.status === 'active' ? '\u6b63\u5e38' : '\u5df2\u7981\u7528'}</Descriptions.Item>\n        </Descriptions>\n      </Card>\n    </div>\n  );\n};\n\n// \u7cfb\u7edf\u8bbe\u7f6e\u9875\u9762\nconst SettingsPage = () => {\n  return (\n    <div style={{ padding: 24 }}>\n      <Title level={4}>\u7cfb\u7edf\u8bbe\u7f6e</Title>\n      <Card>\n        <Descriptions column={1}>\n          <Descriptions.Item label=\"\u7cfb\u7edf\u540d\u79f0\">\u7528\u6237\u7ba1\u7406\u7cfb\u7edf v2.0</Descriptions.Item>\n          <Descriptions.Item label=\"\u8fd0\u884c\u73af\u5883\">\u751f\u4ea7\u73af\u5883</Descriptions.Item>\n          <Descriptions.Item label=\"\u6570\u636e\u5e93\u7248\u672c\">MySQL 8.0</Descriptions.Item>\n        </Descriptions>\n      </Card>\n    </div>\n  );\n};\n\n// \u4e3b\u5e03\u5c40\u7ec4\u4ef6\nconst LayoutWithNav = () => {\n  const navigate = useNavigate();\n  \n  const menuItems = [\n    { key: 'home', label: <Link to=\"/app\">\u9996\u9875\u6982\u89c8</Link> },\n    { key: 'users', label: <Link to=\"/app/users\">\u7528\u6237\u5217\u8868</Link> },\n    { key: 'detail', label: <Link to=\"/app/user/U001\">\u7528\u6237\u8be6\u60c5</Link> },\n    { key: 'settings', label: <Link to=\"/app/settings\">\u7cfb\u7edf\u8bbe\u7f6e</Link> },\n    { \n      key: 'error-500', \n      label: <Link to=\"/app/error?status=500&msg=\u670d\u52a1\u5668\u5185\u90e8\u9519\u8bef\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\">\u89e6\u53d1500\u9519\u8bef</Link> \n    },\n    { \n      key: 'error-403', \n      label: <Link to=\"/app/error?status=403&msg=\u60a8\u6ca1\u6709\u6743\u9650\u8bbf\u95ee\u6b64\u9875\u9762\">\u89e6\u53d1403\u9519\u8bef</Link> \n    },\n    { \n      key: '404', \n      label: <Link to=\"/app/unknown-page\">\u89e6\u53d1404\u9875\u9762</Link> \n    }\n  ];\n\n  return (\n    <Flex vertical gap={24}>\n      <Card>\n        <Flex gap={16} wrap=\"wrap\">\n          {menuItems.map(item => (\n            <Button key={item.key} type=\"link\" style={{ padding: 0 }}>\n              {item.label}\n            </Button>\n          ))}\n        </Flex>\n      </Card>\n      <Card>\n        <Routes>\n          <Route\n            path=\"app/*\"\n            element={\n              <AppChildrenRouter\n                errorPage\n                notFoundPage\n                baseUrl=\"/app\"\n                list={[\n                  {\n                    index: true,\n                    loader: async () => ({ default: HomePage })\n                  },\n                  {\n                    path: 'users',\n                    loader: async () => ({ default: UserListPage })\n                  },\n                  {\n                    path: 'user/:id',\n                    loader: async () => ({ default: UserDetailPage })\n                  },\n                  {\n                    path: 'settings',\n                    loader: async () => ({ default: SettingsPage })\n                  }\n                ]}\n              />\n            }\n          />\n          <Route path=\"*\" element={<Navigate to=\"/app\" />} />\n        </Routes>\n      </Card>\n    </Flex>\n  );\n};\n\nconst BaseExample = () => {\n  return <LayoutWithNav />;\n};\n\nrender(<BaseExample />);\n\n",scope:[{name:"_AppChildrenRouter",packageName:"@kne/current-lib_app-children-router",importStatement:'import * as _AppChildrenRouter from "@kne/app-children-router"',component:a},{name:"_reactRouterDom",packageName:"react-router-dom",component:o},{name:"antd",packageName:"antd",component:r}]},{title:"loadableWithProps \u5de5\u5177\u51fd\u6570",description:"\u6f14\u793a\u5982\u4f55\u4f7f\u7528 loadableWithProps \u52a8\u6001\u52a0\u8f7d\u7ec4\u4ef6\u5e76\u4f20\u9012 props",code:"const { loadableWithProps } = _AppChildrenRouter;\nconst { Button, Space, Card, Form, Input, Select, DatePicker, InputNumber, Typography, Alert, Spin } = antd;\n\nconst { Title, Text, Paragraph } = Typography;\n\n// \u52a8\u6001\u52a0\u8f7d\u7684\u7528\u6237\u8be6\u60c5\u5361\u7247\u7ec4\u4ef6\nconst UserDetailCard = ({ userId, username, email, role, department, onRefresh }) => {\n  return (\n    <Card \n      title={`\u7528\u6237\u4fe1\u606f - ${username}`} \n      extra={<Button type=\"link\" onClick={onRefresh}>\u5237\u65b0</Button>}\n      style={{ marginTop: 16 }}\n    >\n      <Space direction=\"vertical\" size=\"small\" style={{ width: '100%' }}>\n        <Text><strong>\u7528\u6237ID\uff1a</strong>{userId}</Text>\n        <Text><strong>\u90ae\u7bb1\uff1a</strong>{email}</Text>\n        <Text><strong>\u89d2\u8272\uff1a</strong>{role}</Text>\n        <Text><strong>\u90e8\u95e8\uff1a</strong>{department}</Text>\n      </Space>\n    </Card>\n  );\n};\n\n// \u52a8\u6001\u52a0\u8f7d\u7684\u6743\u9650\u914d\u7f6e\u7ec4\u4ef6\nconst PermissionConfig = ({ permissions, onPermissionChange }) => {\n  const permissionOptions = [\n    { label: '\u67e5\u770b\u6570\u636e', value: 'view' },\n    { label: '\u7f16\u8f91\u6570\u636e', value: 'edit' },\n    { label: '\u5220\u9664\u6570\u636e', value: 'delete' },\n    { label: '\u7ba1\u7406\u7528\u6237', value: 'manage_users' },\n    { label: '\u7cfb\u7edf\u914d\u7f6e', value: 'system_config' }\n  ];\n\n  return (\n    <Card title=\"\u6743\u9650\u914d\u7f6e\" style={{ marginTop: 16 }}>\n      <Alert\n        message=\"\u6743\u9650\u8bf4\u660e\"\n        description=\"\u8bf7\u6839\u636e\u7528\u6237\u89d2\u8272\u914d\u7f6e\u76f8\u5e94\u7684\u6743\u9650\uff0c\u6743\u9650\u53d8\u66f4\u5c06\u7acb\u5373\u751f\u6548\"\n        type=\"info\"\n        showIcon\n        style={{ marginBottom: 16 }}\n      />\n      <Select\n        mode=\"multiple\"\n        placeholder=\"\u8bf7\u9009\u62e9\u6743\u9650\"\n        value={permissions}\n        onChange={onPermissionChange}\n        options={permissionOptions}\n        style={{ width: '100%' }}\n      />\n    </Card>\n  );\n};\n\n// \u52a8\u6001\u52a0\u8f7d\u7684\u8868\u5355\u7ec4\u4ef6 - \u6839\u636e\u914d\u7f6e\u751f\u6210\u4e0d\u540c\u7684\u8868\u5355\u5b57\u6bb5\nconst DynamicForm = ({ formType, initialData, onSubmit }) => {\n  const [form] = Form.useForm();\n\n  const formConfigs = {\n    user: {\n      title: '\u7528\u6237\u4fe1\u606f\u8868\u5355',\n      fields: [\n        { name: 'username', label: '\u7528\u6237\u540d', type: 'input', rules: [{ required: true }] },\n        { name: 'email', label: '\u90ae\u7bb1', type: 'input', rules: [{ required: true, type: 'email' }] },\n        { name: 'role', label: '\u89d2\u8272', type: 'select', options: [\n          { label: '\u7ba1\u7406\u5458', value: 'admin' },\n          { label: '\u666e\u901a\u7528\u6237', value: 'user' },\n          { label: '\u8bbf\u5ba2', value: 'guest' }\n        ]}\n      ]\n    },\n    product: {\n      title: '\u5546\u54c1\u4fe1\u606f\u8868\u5355',\n      fields: [\n        { name: 'productName', label: '\u5546\u54c1\u540d\u79f0', type: 'input', rules: [{ required: true }] },\n        { name: 'price', label: '\u4ef7\u683c', type: 'number', rules: [{ required: true }] },\n        { name: 'stock', label: '\u5e93\u5b58', type: 'number', rules: [{ required: true }] },\n        { name: 'category', label: '\u5206\u7c7b', type: 'select', options: [\n          { label: '\u7535\u5b50\u4ea7\u54c1', value: 'electronics' },\n          { label: '\u670d\u88c5', value: 'clothing' },\n          { label: '\u98df\u54c1', value: 'food' }\n        ]}\n      ]\n    },\n    order: {\n      title: '\u8ba2\u5355\u4fe1\u606f\u8868\u5355',\n      fields: [\n        { name: 'orderNo', label: '\u8ba2\u5355\u53f7', type: 'input', rules: [{ required: true }] },\n        { name: 'customerName', label: '\u5ba2\u6237\u59d3\u540d', type: 'input', rules: [{ required: true }] },\n        { name: 'deliveryDate', label: '\u4ea4\u4ed8\u65e5\u671f', type: 'date', rules: [{ required: true }] },\n        { name: 'amount', label: '\u91d1\u989d', type: 'number', rules: [{ required: true }] }\n      ]\n    }\n  };\n\n  const config = formConfigs[formType] || formConfigs.user;\n\n  const renderField = (field) => {\n    const commonProps = {\n      name: field.name,\n      label: field.label,\n      rules: field.rules\n    };\n\n    switch (field.type) {\n      case 'input':\n        return <Form.Item key={field.name} {...commonProps}><Input /></Form.Item>;\n      case 'number':\n        return <Form.Item key={field.name} {...commonProps}><InputNumber style={{ width: '100%' }} /></Form.Item>;\n      case 'select':\n        return (\n          <Form.Item key={field.name} {...commonProps}>\n            <Select options={field.options} />\n          </Form.Item>\n        );\n      case 'date':\n        return <Form.Item key={field.name} {...commonProps}><DatePicker style={{ width: '100%' }} /></Form.Item>;\n      default:\n        return <Form.Item key={field.name} {...commonProps}><Input /></Form.Item>;\n    }\n  };\n\n  return (\n    <Card title={config.title} style={{ marginTop: 16 }}>\n      <Form\n        form={form}\n        layout=\"vertical\"\n        initialValues={initialData}\n        onFinish={onSubmit}\n      >\n        {config.fields.map(renderField)}\n        <Form.Item>\n          <Space>\n            <Button type=\"primary\" htmlType=\"submit\">\u63d0\u4ea4</Button>\n            <Button onClick={() => form.resetFields()}>\u91cd\u7f6e</Button>\n          </Space>\n        </Form.Item>\n      </Form>\n    </Card>\n  );\n};\n\n// \u6f14\u793a loadableWithProps \u7684\u4f7f\u7528\nconst LoadableExample = () => {\n  const [activeTab, setActiveTab] = React.useState('user');\n  const [userData, setUserData] = React.useState({\n    userId: 'U20240001',\n    username: '\u5f20\u4e09',\n    email: 'zhangsan@example.com',\n    role: '\u7ba1\u7406\u5458',\n    department: '\u6280\u672f\u90e8'\n  });\n  const [permissions, setPermissions] = React.useState(['view', 'edit']);\n\n  // \u6a21\u62df\u5f02\u6b65\u52a0\u8f7d\u7528\u6237\u8be6\u60c5\u5361\u7247\n  const UserCard = loadableWithProps(\n    async () => {\n      // \u6a21\u62df API \u8bf7\u6c42\u5ef6\u8fdf\n      await new Promise(resolve => setTimeout(resolve, 800));\n      return { default: UserDetailCard };\n    },\n    {\n      ...userData,\n      onRefresh: () => {\n        setUserData(prev => ({ ...prev, username: prev.username + ' (\u5df2\u5237\u65b0)' }));\n      }\n    },\n    <Card style={{ marginTop: 16 }}>\n      <Spin tip=\"\u52a0\u8f7d\u7528\u6237\u4fe1\u606f\u4e2d...\" />\n    </Card>\n  );\n\n  // \u6a21\u62df\u5f02\u6b65\u52a0\u8f7d\u6743\u9650\u914d\u7f6e\n  const PermissionPanel = loadableWithProps(\n    async () => {\n      await new Promise(resolve => setTimeout(resolve, 600));\n      return { default: PermissionConfig };\n    },\n    {\n      permissions,\n      onPermissionChange: (newPermissions) => setPermissions(newPermissions)\n    },\n    <Card style={{ marginTop: 16 }}>\n      <Spin tip=\"\u52a0\u8f7d\u6743\u9650\u914d\u7f6e\u4e2d...\" />\n    </Card>\n  );\n\n  // \u6a21\u62df\u5f02\u6b65\u52a0\u8f7d\u52a8\u6001\u8868\u5355\n  const ActiveForm = loadableWithProps(\n    async () => {\n      await new Promise(resolve => setTimeout(resolve, 500));\n      return { default: DynamicForm };\n    },\n    {\n      formType: activeTab,\n      initialData: activeTab === 'user' ? { username: '\u65b0\u7528\u6237', role: 'user' } : \n                   activeTab === 'product' ? { productName: '\u65b0\u5546\u54c1', price: 0 } :\n                   { orderNo: 'ORD' + Date.now() },\n      onSubmit: (values) => {\n        console.log('\u8868\u5355\u63d0\u4ea4:', values);\n        alert(`${activeTab === 'user' ? '\u7528\u6237' : activeTab === 'product' ? '\u5546\u54c1' : '\u8ba2\u5355'}\u4fe1\u606f\u5df2\u63d0\u4ea4`);\n      }\n    },\n    <Card style={{ marginTop: 16 }}>\n      <Spin tip=\"\u52a0\u8f7d\u8868\u5355\u4e2d...\" />\n    </Card>\n  );\n\n  return (\n    <div style={{ padding: 24 }}>\n      <Title level={4}>\u52a8\u6001\u7ec4\u4ef6\u52a0\u8f7d\u793a\u4f8b</Title>\n      <Paragraph>\n        \u672c\u793a\u4f8b\u6f14\u793a\u5982\u4f55\u4f7f\u7528 loadableWithProps \u52a8\u6001\u52a0\u8f7d\u7ec4\u4ef6\u5e76\u4f20\u9012\u4e1a\u52a1\u6570\u636e\u3002\u5728\u5b9e\u9645\u5e94\u7528\u4e2d\uff0c\u53ef\u4ee5\u6839\u636e\u4e0d\u540c\u7684\u4e1a\u52a1\u573a\u666f\u52a8\u6001\u52a0\u8f7d\u5bf9\u5e94\u7684\u8868\u5355\u6216\u7ec4\u4ef6\u3002\n      </Paragraph>\n\n      <Space direction=\"vertical\" size=\"large\" style={{ width: '100%' }}>\n        <Card>\n          <Space direction=\"vertical\" size=\"middle\">\n            <div>\n              <Text strong>\u9009\u62e9\u8868\u5355\u7c7b\u578b\uff1a</Text>\n              <Space style={{ marginLeft: 16 }}>\n                <Button \n                  type={activeTab === 'user' ? 'primary' : 'default'}\n                  onClick={() => setActiveTab('user')}\n                >\n                  \u7528\u6237\u8868\u5355\n                </Button>\n                <Button \n                  type={activeTab === 'product' ? 'primary' : 'default'}\n                  onClick={() => setActiveTab('product')}\n                >\n                  \u5546\u54c1\u8868\u5355\n                </Button>\n                <Button \n                  type={activeTab === 'order' ? 'primary' : 'default'}\n                  onClick={() => setActiveTab('order')}\n                >\n                  \u8ba2\u5355\u8868\u5355\n                </Button>\n              </Space>\n            </div>\n\n            <Alert\n              message=\"\u4e1a\u52a1\u573a\u666f\u8bf4\u660e\"\n              description=\"\u5728\u540e\u53f0\u7ba1\u7406\u7cfb\u7edf\u4e2d\uff0c\u4e0d\u540c\u7c7b\u578b\u7684\u6570\u636e\u9700\u8981\u4e0d\u540c\u7684\u8868\u5355\u914d\u7f6e\u3002\u901a\u8fc7\u52a8\u6001\u52a0\u8f7d\uff0c\u53ef\u4ee5\u6309\u9700\u52a0\u8f7d\u5bf9\u5e94\u7684\u8868\u5355\u7ec4\u4ef6\uff0c\u63d0\u5347\u9875\u9762\u6027\u80fd\u3002\"\n              type=\"info\"\n              showIcon\n            />\n          </Space>\n        </Card>\n\n        {UserCard}\n        {PermissionPanel}\n        {ActiveForm}\n      </Space>\n    </div>\n  );\n};\n\nrender(<LoadableExample />);\n\n",scope:[{name:"_AppChildrenRouter",packageName:"@kne/current-lib_app-children-router",importStatement:'import * as _AppChildrenRouter from "@kne/app-children-router"',component:a},{name:"antd",packageName:"antd",component:r}]},{title:"\u81ea\u5b9a\u4e49\u9519\u8bef\u9875\u9762",description:"\u5c55\u793a\u5982\u4f55\u81ea\u5b9a\u4e49 Error \u548c NotFound \u9875\u9762",code:"const { default: AppChildrenRouter, Error, NotFound } = _AppChildrenRouter;\nconst { Navigate, Route, Routes, Link, useLocation, useNavigate } = _reactRouterDom;\nconst { Flex, Card, Result, Button, Typography, Space, Alert } = antd;\n\nconst { Title, Text, Paragraph } = Typography;\n\n// \u8ba2\u5355\u7cfb\u7edf - \u81ea\u5b9a\u4e49\u670d\u52a1\u5668\u9519\u8bef\u9875\u9762\nconst OrderErrorPage = () => {\n  const location = useLocation();\n  const navigate = useNavigate();\n  const searchParams = new URLSearchParams(location.search);\n  const status = searchParams.get('status') || '500';\n  const msg = searchParams.get('msg') || '\u7cfb\u7edf\u7e41\u5fd9\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5';\n\n  const errorConfig = {\n    500: {\n      title: '\u8ba2\u5355\u5904\u7406\u5931\u8d25',\n      icon: 'error',\n      suggestions: [\n        '\u8bf7\u68c0\u67e5\u7f51\u7edc\u8fde\u63a5\u662f\u5426\u6b63\u5e38',\n        '\u8ba2\u5355\u6570\u636e\u53ef\u80fd\u6b63\u5728\u5904\u7406\u4e2d\uff0c\u8bf7\u7a0d\u540e\u5237\u65b0\u9875\u9762',\n        '\u5982\u95ee\u9898\u6301\u7eed\uff0c\u8bf7\u8054\u7cfb\u5ba2\u670d\uff1a400-123-4567'\n      ]\n    },\n    403: {\n      title: '\u65e0\u6743\u9650\u8bbf\u95ee\u8ba2\u5355',\n      icon: 'warning',\n      suggestions: [\n        '\u60a8\u53ef\u80fd\u6ca1\u6709\u67e5\u770b\u6b64\u8ba2\u5355\u7684\u6743\u9650',\n        '\u8bf7\u786e\u8ba4\u8ba2\u5355\u662f\u5426\u5c5e\u4e8e\u5f53\u524d\u8d26\u6237',\n        '\u5982\u9700\u5e2e\u52a9\uff0c\u8bf7\u8054\u7cfb\u8ba2\u5355\u7ba1\u7406\u5458'\n      ]\n    },\n    404: {\n      title: '\u8ba2\u5355\u4e0d\u5b58\u5728',\n      icon: 'info',\n      suggestions: [\n        '\u8ba2\u5355\u53ef\u80fd\u5df2\u88ab\u5220\u9664\u6216\u53d6\u6d88',\n        '\u8bf7\u68c0\u67e5\u8ba2\u5355\u53f7\u662f\u5426\u6b63\u786e',\n        '\u8fd4\u56de\u8ba2\u5355\u5217\u8868\u91cd\u65b0\u67e5\u627e'\n      ]\n    }\n  };\n\n  const config = errorConfig[status] || errorConfig[500];\n\n  return (\n    <Result\n      status={status === '404' ? '404' : (status === '403' ? '403' : '500')}\n      title={`${config.title} (${status})`}\n      subTitle={msg}\n      extra={\n        <Space direction=\"vertical\" size=\"large\" style={{ width: '100%', maxWidth: 400 }}>\n          <Alert\n            message=\"\u5efa\u8bae\u64cd\u4f5c\"\n            description={\n              <ul style={{ margin: 0, paddingLeft: 20 }}>\n                {config.suggestions.map((item, index) => (\n                  <li key={index}>{item}</li>\n                ))}\n              </ul>\n            }\n            type=\"info\"\n            showIcon\n          />\n          <Space>\n            <Button type=\"primary\" onClick={() => navigate('/app/orders')}>\n              \u8fd4\u56de\u8ba2\u5355\u5217\u8868\n            </Button>\n            <Button onClick={() => window.location.reload()}>\n              \u5237\u65b0\u9875\u9762\n            </Button>\n            <Button onClick={() => navigate('/app')}>\n              \u8fd4\u56de\u9996\u9875\n            </Button>\n          </Space>\n        </Space>\n      }\n    />\n  );\n};\n\n// \u5546\u54c1\u7cfb\u7edf - \u81ea\u5b9a\u4e49 404 \u9875\u9762\nconst ProductNotFoundPage = () => {\n  const navigate = useNavigate();\n  \n  return (\n    <Result\n      status=\"404\"\n      title=\"\u5546\u54c1\u4e0d\u5b58\u5728\u6216\u5df2\u4e0b\u67b6\"\n      subTitle=\"\u62b1\u6b49\uff0c\u60a8\u8bbf\u95ee\u7684\u5546\u54c1\u53ef\u80fd\u5df2\u88ab\u5220\u9664\u3001\u4e0b\u67b6\u6216\u4ece\u672a\u5b58\u5728\"\n      extra={\n        <Space direction=\"vertical\" size=\"middle\">\n          <Alert\n            message=\"\u53ef\u80fd\u7684\u539f\u56e0\"\n            description={\n              <ul style={{ margin: 0, paddingLeft: 20 }}>\n                <li>\u5546\u54c1\u5df2\u552e\u7f44\u5e76\u4e0b\u67b6</li>\n                <li>\u5546\u54c1\u94fe\u63a5\u8f93\u5165\u9519\u8bef</li>\n                <li>\u5546\u54c1\u56e0\u8fdd\u89c4\u88ab\u5e73\u53f0\u4e0b\u67b6</li>\n                <li>\u5546\u54c1\u5df2\u8fc7\u671f\u6216\u6d3b\u52a8\u5df2\u7ed3\u675f</li>\n              </ul>\n            }\n            type=\"warning\"\n            showIcon\n          />\n          <Space>\n            <Button type=\"primary\" onClick={() => navigate('/app/products')}>\n              \u6d4f\u89c8\u5546\u54c1\u5217\u8868\n            </Button>\n            <Button onClick={() => navigate('/app')}>\n              \u8fd4\u56de\u9996\u9875\n            </Button>\n            <Button onClick={() => window.history.back()}>\n              \u8fd4\u56de\u4e0a\u4e00\u9875\n            </Button>\n          </Space>\n        </Space>\n      }\n    />\n  );\n};\n\n// \u9996\u9875\nconst HomePage = () => (\n  <div style={{ padding: 24 }}>\n    <Title level={4}>\u7535\u5546\u540e\u53f0\u7ba1\u7406\u7cfb\u7edf</Title>\n    <Paragraph>\n      \u672c\u793a\u4f8b\u6f14\u793a\u5982\u4f55\u5728\u7535\u5546\u7cfb\u7edf\u4e2d\u81ea\u5b9a\u4e49\u9519\u8bef\u9875\u9762\u3002\u901a\u8fc7\u81ea\u5b9a\u4e49\u9519\u8bef\u9875\u9762\uff0c\u53ef\u4ee5\u4e3a\u7528\u6237\u63d0\u4f9b\u66f4\u53cb\u597d\u7684\u63d0\u793a\u548c\u5f15\u5bfc\u3002\n    </Paragraph>\n    <Alert\n      message=\"\u4e1a\u52a1\u573a\u666f\u8bf4\u660e\"\n      description=\"\u5728\u5b9e\u9645\u4e1a\u52a1\u4e2d\uff0c\u4e0d\u540c\u7684\u9519\u8bef\u72b6\u6001\u53ef\u80fd\u9700\u8981\u4e0d\u540c\u7684\u5904\u7406\u65b9\u5f0f\u548c\u63d0\u793a\u4fe1\u606f\u3002\u4f8b\u5982\u8ba2\u5355\u9519\u8bef\u3001\u5546\u54c1\u4e0d\u5b58\u5728\u3001\u6743\u9650\u4e0d\u8db3\u7b49\u573a\u666f\uff0c\u90fd\u53ef\u4ee5\u901a\u8fc7\u81ea\u5b9a\u4e49\u9875\u9762\u6765\u63d0\u5347\u7528\u6237\u4f53\u9a8c\u3002\"\n      type=\"info\"\n      showIcon\n    />\n  </div>\n);\n\n// \u8ba2\u5355\u5217\u8868\u9875\nconst OrdersPage = () => (\n  <div style={{ padding: 24 }}>\n    <Title level={4}>\u8ba2\u5355\u5217\u8868</Title>\n    <Text>\u8ba2\u5355\u6570\u636e\u52a0\u8f7d\u4e2d...</Text>\n  </div>\n);\n\n// \u5546\u54c1\u5217\u8868\u9875\nconst ProductsPage = () => (\n  <div style={{ padding: 24 }}>\n    <Title level={4}>\u5546\u54c1\u7ba1\u7406</Title>\n    <Text>\u5546\u54c1\u6570\u636e\u52a0\u8f7d\u4e2d...</Text>\n  </div>\n);\n\nconst CustomPagesExample = () => {\n  const menuItems = [\n    { key: 'home', label: <Link to=\"/app\">\u7cfb\u7edf\u9996\u9875</Link> },\n    { key: 'orders', label: <Link to=\"/app/orders\">\u8ba2\u5355\u7ba1\u7406</Link> },\n    { key: 'products', label: <Link to=\"/app/products\">\u5546\u54c1\u7ba1\u7406</Link> },\n    { \n      key: 'error-500', \n      label: <Link to=\"/app/error?status=500&msg=\u8ba2\u5355\u652f\u4ed8\u5904\u7406\u5931\u8d25\uff0c\u94f6\u884c\u7cfb\u7edf\u8fd4\u56de\u8d85\u65f6\">\u6a21\u62df\u8ba2\u5355500\u9519\u8bef</Link> \n    },\n    { \n      key: 'error-403', \n      label: <Link to=\"/app/error?status=403&msg=\u60a8\u6ca1\u6709\u6743\u9650\u67e5\u770b\u6b64\u8ba2\u5355\u7684\u8be6\u7ec6\u4fe1\u606f\">\u6a21\u62df\u8ba2\u5355403\u9519\u8bef</Link> \n    },\n    { \n      key: 'error-404', \n      label: <Link to=\"/app/error?status=404&msg=\u8ba2\u5355\u53f7 ORD202403150001 \u4e0d\u5b58\u5728\">\u6a21\u62df\u8ba2\u5355404\u9519\u8bef</Link> \n    },\n    { \n      key: 'notfound', \n      label: <Link to=\"/app/404\">\u5546\u54c1\u4e0d\u5b58\u5728\u9875\u9762</Link> \n    },\n    { \n      key: 'unknown', \n      label: <Link to=\"/app/unknown-product\">\u89e6\u53d1\u7cfb\u7edf404</Link> \n    }\n  ];\n\n  return (\n    <Flex vertical gap={24}>\n      <Card>\n        <Flex gap={16} wrap=\"wrap\">\n          {menuItems.map(item => (\n            <Button key={item.key} type=\"link\" style={{ padding: 0 }}>\n              {item.label}\n            </Button>\n          ))}\n        </Flex>\n      </Card>\n      <Card>\n        <Routes>\n          <Route\n            path=\"app/*\"\n            element={\n              <AppChildrenRouter\n                baseUrl=\"/app\"\n                list={[\n                  {\n                    index: true,\n                    loader: async () => ({ default: HomePage })\n                  },\n                  {\n                    path: 'orders',\n                    loader: async () => ({ default: OrdersPage })\n                  },\n                  {\n                    path: 'products',\n                    loader: async () => ({ default: ProductsPage })\n                  },\n                  {\n                    path: 'error',\n                    element: <OrderErrorPage />\n                  },\n                  {\n                    path: '404',\n                    element: <ProductNotFoundPage />\n                  }\n                ]}\n                children={<ProductNotFoundPage />}\n              />\n            }\n          />\n          <Route path=\"*\" element={<Navigate to=\"/app\" />} />\n        </Routes>\n      </Card>\n    </Flex>\n  );\n};\n\nrender(<CustomPagesExample />);\n\n",scope:[{name:"_AppChildrenRouter",packageName:"@kne/current-lib_app-children-router",importStatement:'import * as _AppChildrenRouter from "@kne/app-children-router"',component:a},{name:"_reactRouterDom",packageName:"react-router-dom",component:o},{name:"antd",packageName:"antd",component:r}]},{title:"\u5d4c\u5957\u8def\u7531",description:"\u5c55\u793a\u5982\u4f55\u5728\u5e03\u5c40\u4e2d\u4f7f\u7528\u5d4c\u5957\u8def\u7531\uff0c\u7ed3\u5408 element \u5c5e\u6027\u5b9e\u73b0\u590d\u6742\u7684\u8def\u7531\u7ed3\u6784",code:"const { default: AppChildrenRouter } = _AppChildrenRouter;\nconst { Route, Routes, Link, Outlet, Navigate, useLocation } = _reactRouterDom;\nconst { Flex, Card, Menu, Typography, Table, Descriptions, Statistic, Row, Col, Button, Space, Tag, Avatar, Form, Input, Switch, Divider } = antd;\n\nconst { Title, Text, Paragraph } = Typography;\n\n// \u540e\u53f0\u7ba1\u7406\u5e03\u5c40\u7ec4\u4ef6\nconst AdminLayout = () => {\n  const location = useLocation();\n  const selectedKey = location.pathname.split('/')[2] || 'home';\n\n  const menuItems = [\n    {\n      key: 'home',\n      icon: '\ud83d\udcca',\n      label: <Link to=\"/app\">\u9996\u9875\u6982\u89c8</Link>\n    },\n    {\n      key: 'users',\n      icon: '\ud83d\udc65',\n      label: <Link to=\"/app/users\">\u7528\u6237\u7ba1\u7406</Link>\n    },\n    {\n      key: 'products',\n      icon: '\ud83d\udce6',\n      label: <Link to=\"/app/products\">\u5546\u54c1\u7ba1\u7406</Link>\n    },\n    {\n      key: 'orders',\n      icon: '\ud83d\uded2',\n      label: <Link to=\"/app/orders\">\u8ba2\u5355\u7ba1\u7406</Link>\n    },\n    {\n      key: 'reports',\n      icon: '\ud83d\udcc8',\n      label: <Link to=\"/app/reports\">\u6570\u636e\u62a5\u8868</Link>\n    },\n    {\n      key: 'settings',\n      icon: '\u2699\ufe0f',\n      label: <Link to=\"/app/settings\">\u7cfb\u7edf\u8bbe\u7f6e</Link>\n    },\n    {\n      key: 'profile',\n      icon: '\ud83d\udc64',\n      label: <Link to=\"/app/profile\">\u4e2a\u4eba\u4e2d\u5fc3</Link>\n    }\n  ];\n\n  return (\n    <Flex style={{ minHeight: '100vh' }}>\n      {/* \u5de6\u4fa7\u83dc\u5355 */}\n      <div style={{ width: 240, background: '#001529', color: '#fff' }}>\n        <div style={{ height: 64, padding: 16, borderBottom: '1px solid #002140' }}>\n          <Title level={4} style={{ color: '#fff', margin: 0 }}>\n            \u7ba1\u7406\u540e\u53f0\n          </Title>\n        </div>\n        <Menu\n          theme=\"dark\"\n          mode=\"inline\"\n          selectedKeys={[selectedKey]}\n          items={menuItems}\n        />\n      </div>\n\n      {/* \u53f3\u4fa7\u5185\u5bb9 */}\n      <div style={{ flex: 1, background: '#f0f2f5', padding: 24 }}>\n        <Outlet />\n      </div>\n    </Flex>\n  );\n};\n\n// \u9996\u9875\u6982\u89c8\nconst HomePage = () => {\n  const stats = [\n    { title: '\u4eca\u65e5\u8ba2\u5355', value: 1234, prefix: '\ud83d\udce6', suffix: '\u5355' },\n    { title: '\u4eca\u65e5\u9500\u552e\u989d', value: 56890, prefix: '\xa5', precision: 2 },\n    { title: '\u65b0\u589e\u7528\u6237', value: 89, prefix: '\ud83d\udc65', suffix: '\u4eba' },\n    { title: '\u5f85\u5904\u7406\u5de5\u5355', value: 23, prefix: '\u23f0', suffix: '\u4e2a' }\n  ];\n\n  const recentOrders = [\n    { id: 'ORD001', customer: '\u5f20\u4e09', amount: 299.00, status: 'completed', time: '10:30' },\n    { id: 'ORD002', customer: '\u674e\u56db', amount: 599.00, status: 'pending', time: '10:45' },\n    { id: 'ORD003', customer: '\u738b\u4e94', amount: 1299.00, status: 'processing', time: '11:00' }\n  ];\n\n  const statusMap = {\n    completed: { text: '\u5df2\u5b8c\u6210', color: 'success' },\n    pending: { text: '\u5f85\u5904\u7406', color: 'warning' },\n    processing: { text: '\u5904\u7406\u4e2d', color: 'processing' }\n  };\n\n  return (\n    <div>\n      <Title level={4}>\u9996\u9875\u6982\u89c8</Title>\n      <Row gutter={16} style={{ marginBottom: 24 }}>\n        {stats.map((stat, index) => (\n          <Col span={6} key={index}>\n            <Card>\n              <Statistic\n                title={stat.title}\n                value={stat.value}\n                prefix={stat.prefix}\n                suffix={stat.suffix}\n                precision={stat.precision}\n              />\n            </Card>\n          </Col>\n        ))}\n      </Row>\n\n      <Row gutter={16}>\n        <Col span={12}>\n          <Card title=\"\u6700\u8fd1\u8ba2\u5355\">\n            <Table\n              dataSource={recentOrders}\n              rowKey=\"id\"\n              pagination={false}\n              size=\"small\"\n            >\n              <Table.Column title=\"\u8ba2\u5355\u53f7\" dataIndex=\"id\" key=\"id\" />\n              <Table.Column title=\"\u5ba2\u6237\" dataIndex=\"customer\" key=\"customer\" />\n              <Table.Column \n                title=\"\u91d1\u989d\" \n                dataIndex=\"amount\" \n                key=\"amount\"\n                render={(val) => `\xa5${val.toFixed(2)}`}\n              />\n              <Table.Column \n                title=\"\u72b6\u6001\" \n                dataIndex=\"status\" \n                key=\"status\"\n                render={(status) => (\n                  <Tag color={statusMap[status].color}>{statusMap[status].text}</Tag>\n                )}\n              />\n            </Table>\n          </Card>\n        </Col>\n        <Col span={12}>\n          <Card title=\"\u5feb\u6377\u64cd\u4f5c\">\n            <Space direction=\"vertical\" style={{ width: '100%' }}>\n              <Button type=\"primary\" block>\u521b\u5efa\u65b0\u8ba2\u5355</Button>\n              <Button block>\u6dfb\u52a0\u5546\u54c1</Button>\n              <Button block>\u7528\u6237\u7ba1\u7406</Button>\n            </Space>\n          </Card>\n        </Col>\n      </Row>\n    </div>\n  );\n};\n\n// \u7528\u6237\u7ba1\u7406\u9875\u9762\nconst UsersPage = () => {\n  const columns = [\n    { title: '\u7528\u6237ID', dataIndex: 'id', key: 'id' },\n    { \n      title: '\u7528\u6237\u4fe1\u606f', \n      key: 'userInfo',\n      render: (_, record) => (\n        <Space>\n          <Avatar>{record.username[0]}</Avatar>\n          <span>{record.username}</span>\n        </Space>\n      )\n    },\n    { title: '\u90ae\u7bb1', dataIndex: 'email', key: 'email' },\n    { \n      title: '\u89d2\u8272', \n      dataIndex: 'role', \n      key: 'role',\n      render: (role) => (\n        <Tag color={role === 'admin' ? 'red' : 'blue'}>\n          {role === 'admin' ? '\u7ba1\u7406\u5458' : '\u666e\u901a\u7528\u6237'}\n        </Tag>\n      )\n    },\n    { \n      title: '\u72b6\u6001', \n      dataIndex: 'status', \n      key: 'status',\n      render: (status) => (\n        <Tag color={status === 'active' ? 'success' : 'default'}>\n          {status === 'active' ? '\u6b63\u5e38' : '\u7981\u7528'}\n        </Tag>\n      )\n    },\n    {\n      title: '\u64cd\u4f5c',\n      key: 'action',\n      render: () => (\n        <Space>\n          <a>\u7f16\u8f91</a>\n          <a>\u67e5\u770b</a>\n          <a>\u5220\u9664</a>\n        </Space>\n      )\n    }\n  ];\n\n  const mockData = [\n    { id: 'U001', username: '\u5f20\u4e09', email: 'zhangsan@example.com', role: 'admin', status: 'active' },\n    { id: 'U002', username: '\u674e\u56db', email: 'lisi@example.com', role: 'user', status: 'active' },\n    { id: 'U003', username: '\u738b\u4e94', email: 'wangwu@example.com', role: 'user', status: 'inactive' }\n  ];\n\n  return (\n    <div>\n      <Title level={4}>\u7528\u6237\u7ba1\u7406</Title>\n      <Card>\n        <Table columns={columns} dataSource={mockData} rowKey=\"id\" />\n      </Card>\n    </div>\n  );\n};\n\n// \u5546\u54c1\u7ba1\u7406\u9875\u9762\nconst ProductsPage = () => {\n  const columns = [\n    { title: '\u5546\u54c1ID', dataIndex: 'id', key: 'id' },\n    { title: '\u5546\u54c1\u540d\u79f0', dataIndex: 'name', key: 'name' },\n    { title: '\u5206\u7c7b', dataIndex: 'category', key: 'category' },\n    { \n      title: '\u4ef7\u683c', \n      dataIndex: 'price', \n      key: 'price',\n      render: (val) => `\xa5${val.toFixed(2)}`\n    },\n    { title: '\u5e93\u5b58', dataIndex: 'stock', key: 'stock' },\n    {\n      title: '\u72b6\u6001',\n      dataIndex: 'status',\n      key: 'status',\n      render: (status) => (\n        <Tag color={status === 'on_sale' ? 'success' : 'default'}>\n          {status === 'on_sale' ? '\u5728\u552e' : '\u4e0b\u67b6'}\n        </Tag>\n      )\n    }\n  ];\n\n  const mockData = [\n    { id: 'P001', name: 'iPhone 15 Pro', category: '\u7535\u5b50\u4ea7\u54c1', price: 8999, stock: 156, status: 'on_sale' },\n    { id: 'P002', name: 'MacBook Pro', category: '\u7535\u5b50\u4ea7\u54c1', price: 14999, stock: 89, status: 'on_sale' },\n    { id: 'P003', name: 'AirPods Pro', category: '\u7535\u5b50\u4ea7\u54c1', price: 1999, stock: 0, status: 'off_shelf' }\n  ];\n\n  return (\n    <div>\n      <Title level={4}>\u5546\u54c1\u7ba1\u7406</Title>\n      <Card>\n        <Table columns={columns} dataSource={mockData} rowKey=\"id\" />\n      </Card>\n    </div>\n  );\n};\n\n// \u8ba2\u5355\u7ba1\u7406\u9875\u9762\nconst OrdersPage = () => {\n  return (\n    <div>\n      <Title level={4}>\u8ba2\u5355\u7ba1\u7406</Title>\n      <Card>\n        <Paragraph>\u8ba2\u5355\u7ba1\u7406\u9875\u9762\uff0c\u7528\u4e8e\u67e5\u770b\u548c\u5904\u7406\u6240\u6709\u8ba2\u5355\u3002</Paragraph>\n      </Card>\n    </div>\n  );\n};\n\n// \u6570\u636e\u62a5\u8868\u9875\u9762\nconst ReportsPage = () => {\n  return (\n    <div>\n      <Title level={4}>\u6570\u636e\u62a5\u8868</Title>\n      <Card>\n        <Paragraph>\u6570\u636e\u62a5\u8868\u9875\u9762\uff0c\u7528\u4e8e\u67e5\u770b\u5404\u7c7b\u7edf\u8ba1\u62a5\u8868\u3002</Paragraph>\n      </Card>\n    </div>\n  );\n};\n\n// \u7cfb\u7edf\u8bbe\u7f6e\u9875\u9762\nconst SettingsPage = () => {\n  const [form] = Form.useForm();\n\n  return (\n    <div>\n      <Title level={4}>\u7cfb\u7edf\u8bbe\u7f6e</Title>\n      <Card>\n        <Form form={form} layout=\"vertical\" style={{ maxWidth: 600 }}>\n          <Form.Item label=\"\u7cfb\u7edf\u540d\u79f0\" name=\"systemName\" initialValue=\"\u540e\u53f0\u7ba1\u7406\u7cfb\u7edf\">\n            <Input />\n          </Form.Item>\n          <Form.Item label=\"\u7cfb\u7edf\u63cf\u8ff0\" name=\"systemDesc\" initialValue=\"\u8fd9\u662f\u4e00\u4e2a\u529f\u80fd\u5f3a\u5927\u7684\u540e\u53f0\u7ba1\u7406\u7cfb\u7edf\">\n            <Input.TextArea rows={3} />\n          </Form.Item>\n          <Divider />\n          <Form.Item label=\"\u5f00\u542f\u7528\u6237\u6ce8\u518c\" name=\"enableRegister\" valuePropName=\"checked\" initialValue={true}>\n            <Switch />\n          </Form.Item>\n          <Form.Item label=\"\u5f00\u542f\u90ae\u7bb1\u9a8c\u8bc1\" name=\"enableEmailVerify\" valuePropName=\"checked\" initialValue={false}>\n            <Switch />\n          </Form.Item>\n          <Form.Item>\n            <Button type=\"primary\">\u4fdd\u5b58\u8bbe\u7f6e</Button>\n          </Form.Item>\n        </Form>\n      </Card>\n    </div>\n  );\n};\n\n// \u4e2a\u4eba\u4e2d\u5fc3\u9875\u9762\nconst ProfilePage = () => {\n  return (\n    <div>\n      <Title level={4}>\u4e2a\u4eba\u4e2d\u5fc3</Title>\n      <Card>\n        <Descriptions bordered column={2}>\n          <Descriptions.Item label=\"\u7528\u6237\u540d\">admin</Descriptions.Item>\n          <Descriptions.Item label=\"\u90ae\u7bb1\">admin@example.com</Descriptions.Item>\n          <Descriptions.Item label=\"\u89d2\u8272\">\u7ba1\u7406\u5458</Descriptions.Item>\n          <Descriptions.Item label=\"\u90e8\u95e8\">\u6280\u672f\u90e8</Descriptions.Item>\n          <Descriptions.Item label=\"\u6ce8\u518c\u65f6\u95f4\">2024-01-01</Descriptions.Item>\n          <Descriptions.Item label=\"\u6700\u540e\u767b\u5f55\">2024-03-20 15:30</Descriptions.Item>\n        </Descriptions>\n      </Card>\n    </div>\n  );\n};\n\n// \u5d4c\u5957\u8def\u7531\u793a\u4f8b\nconst NestedRoutesExample = () => {\n  return (\n    <Routes>\n      <Route path=\"app/*\" element={<AdminLayout />}>\n        <Route index element={<HomePage />} />\n        <Route\n          path=\"*\"\n          element={\n            <AppChildrenRouter\n              notFoundPage\n              baseUrl=\"/app\"\n              list={[\n                {\n                  path: 'users',\n                  element: <UsersPage />\n                },\n                {\n                  path: 'products',\n                  loader: async () => ({ default: ProductsPage })\n                },\n                {\n                  path: 'orders',\n                  loader: async () => ({ default: OrdersPage })\n                },\n                {\n                  path: 'reports',\n                  loader: async () => ({ default: ReportsPage })\n                },\n                {\n                  path: 'settings',\n                  loader: async () => ({ default: SettingsPage })\n                },\n                {\n                  path: 'profile',\n                  loader: async () => ({ default: ProfilePage })\n                }\n              ]}\n            />\n          }\n        />\n      </Route>\n      <Route path=\"*\" element={<Navigate to=\"/app\" />} />\n    </Routes>\n  );\n};\n\nrender(<NestedRoutesExample />);\n\n",scope:[{name:"_AppChildrenRouter",packageName:"@kne/current-lib_app-children-router",importStatement:'import * as _AppChildrenRouter from "@kne/app-children-router"',component:a},{name:"_reactRouterDom",packageName:"react-router-dom",component:o},{name:"antd",packageName:"antd",component:r}]}]}}}}]);
